import json
import sympy as sp
from sympy.logic.boolalg import And, Or, Not, Xor, BooleanTrue, BooleanFalse

# Decode hidden Boolean gates from their exact affine coefficients. The
# threshold compiler uses symbolic Shannon cofactors; it does not run the net.
def node(op, *args):
    if op == "input":
        return {"op": op, "index": args[0]}
    if op == "not":
        return {"op": op, "arg": args[0]}
    return {"op": op, "left": args[0], "right": args[1]}

def to_ast(e):
    if e == sp.true or e is BooleanTrue():
        return True
    if e == sp.false or e is BooleanFalse():
        return False
    if e in symbols_to_inputs:
        return {"op": "input", "index": symbols_to_inputs[e]}
    if e.func == Not:
        return {"op": "not", "arg": to_ast(e.args[0])}
    if e.func in (And, Or, Xor):
        op = {And: "and", Or: "or", Xor: "xor"}[e.func]
        items = [to_ast(a) for a in e.args]
        out = items[0]
        for item in items[1:]:
            out = node(op, out, item)
        return out
    raise ValueError("Unsupported symbolic expression: " + str(e))

def threshold_expr(coeffs, bias, vars_):
    # Returns the Boolean expression for bias + sum(coeffs[i]*vars_[i]) > 0.
    # Cofactors simplify algebraically and memoize by (variable, threshold).
    terms = [(int(c), v) for c, v in zip(coeffs, vars_) if int(c) != 0]
    terms.sort(key=lambda z: -abs(z[0]))
    weights = [c for c, _ in terms]
    xs = [v for _, v in terms]
    suffix_min = [0] * (len(xs) + 1)
    for i in range(len(xs) - 1, -1, -1):
        suffix_min[i] = suffix_min[i + 1] + min(0, weights[i])
    memo = {}
    def rec(i, t):
        # Need remaining weighted sum >= t, where t = 1-bias.
        if suffix_min[i] >= t:
            return sp.true
        if sum(max(0, w) for w in weights[i:]) < t:
            return sp.false
        if i == len(xs):
            return sp.true if 0 >= t else sp.false
        key = (i, t)
        if key in memo:
            return memo[key]
        w, x = weights[i], xs[i]
        lo = rec(i + 1, t)
        hi = rec(i + 1, t - w)
        ans = sp.Or(sp.And(sp.Not(x), lo), sp.And(x, hi))
        memo[key] = sp.simplify_logic(ans, force=False)
        return memo[key]
    return rec(0, 1 - int(bias))

symbols_to_inputs = {}
inputs = [sp.Symbol("x%d" % i) for i in range(10)]
symbols_to_inputs.update({x: i for i, x in enumerate(inputs)})

# h channels are represented symbolically. For each triple, the first two
# channels carry the gate and the third is zero, matching the published layout.
