        coeffs = [int(round(float(v))) for v in row]
        # Reduce the affine row through the known triple encoding.
        terms = {}
        bias = int(round(float(b[j])))
        for k, c in enumerate(coeffs):
            if not c:
                continue
            if k < 10:
                terms[h[k]] = terms.get(h[k], 0) + c
            elif (k - 10) % 3 in (0, 1):
                terms[h[k]] = terms.get(h[k], 0) + c
            else:
                terms[h[k]] = terms.get(h[k], 0) - c
