        vars_ = list(terms)
        expr = threshold_expr([terms[v] for v in vars_], bias, vars_)
        new_h[j] = expr
        new_h[j + 1] = expr
        new_h[j + 2] = sp.false
    h = new_h

# The output head compares the encoded final triple against the fixed biases.
