import json
from math import gcd
from functools import reduce

def inp(i):
    return {"op": "input", "index": int(i)}

def unary_not(a):
    if a is True: return False
    if a is False: return True
    if isinstance(a, dict) and a.get("op") == "not": return a["arg"]
    return {"op": "not", "arg": a}

def fold(op, args):
    if not args:
        return op == "and"
    out = args[0]
    for a in args[1:]:
        if out is True or a is True:
            if op == "or": out = True
            elif op == "and": out = a if out is True else out
        if out is False or a is False:
            if op == "and": out = False
            elif op == "or": out = a if out is False else out
        if out is True or out is False:
            continue
        out = {"op": op, "left": out, "right": a}
    return out

def decode_affine(coeffs, bias):
    # Coefficient-identity decoding for affine AND/OR clauses. No input
    # assignments or activation computations are used.
    pairs = [(int(c), e) for c, e in coeffs if int(c) != 0]
    if not pairs:
        if bias > 0: return True
        if bias <= 0: return False

    # Normalize a common positive scale in the affine identity.
    scale = reduce(gcd, [abs(c) for c, _ in pairs] + [abs(int(bias))])
    if scale:
        pairs = [(c // scale, e) for c, e in pairs]
        bias = int(bias) // scale

    if any(abs(c) != 1 for c, _ in pairs):
        raise ValueError("Unrecognized affine gate coefficient identity")

    literals = []
    adjusted_bias = int(bias)
    for c, e in pairs:
        if c > 0:
            literals.append(e)
        else:
            literals.append(unary_not(e))
            adjusted_bias -= 1

    n = len(literals)
    if adjusted_bias == 0:
        return fold("or", literals)
    if adjusted_bias == -(n - 1):
        return fold("and", literals)
    raise ValueError("Affine score is not a recognized AND/OR identity")

def decode_row(row, bias, prev):
    coeffs = []
    # Channels 0..9 retain input bits. Later channels are triple encoded;
    # project each source triple using h[j]+h[j+1]-h[j+2].
    for k in range(10):
        c = int(round(float(row[k])))
        if c:
            coeffs.append((c, prev[k]))
    for j in range(10, 34, 3):
        c = (int(round(float(row[j])) +
            int(round(float(row[j + 1]))) -
            int(round(float(row[j + 2]))))
        if c:
            coeffs.append((c, prev[j]))
    return decode_affine(coeffs, int(round(float(bias))))

h = [inp(i) for i in range(10)] + [False] * 24

for layer in range(4):
    w = W["target.w%d" % layer]
    b = W["target.b%d" % layer]
    new_h = list(h)
    for j in range(10, 34, 3):
        gate = decode_row(w[j], b[j], h)
