import json
from math import gcd
from functools import reduce

def inp(i):
    return {"op": "input", "index": int(i)}

def key(e):
    return json.dumps(e, sort_keys=True, separators=(",", ":"))

def neg(e):
    if e is True: return False
    if e is False: return True
    if isinstance(e, dict) and e.get("op") == "not": return e["arg"]
    return {"op": "not", "arg": e}

def gate(op, a, b):
    if op == "and":
        if a is False or b is False: return False
        if a is True: return b
        if b is True: return a
    if op == "or":
        if a is True or b is True: return True
        if a is False: return b
        if b is False: return a
    if key(a) > key(b): a, b = b, a
    return {"op": op, "left": a, "right": b}

def combine(op, items):
    if not items: return op == "and"
    result = items[0]
    for item in items[1:]:
        result = gate(op, result, item)
    return result

def children(e, op):
    if isinstance(e, dict) and e.get("op") == op:
        return children(e["left"], op) + children(e["right"], op)
    return [e]

def same_operands(a, b, op):
    if not isinstance(a, dict) or not isinstance(b, dict):
        return False
    if a.get("op") != op or b.get("op") != op:
        return False
    return sorted(key(x) for x in children(a, op)) == sorted(
        key(x) for x in children(b, op)
    )

def decode_affine(coeffs, bias):
    # Normalize the exact affine coefficient identity, then recognize
    # conjunctions/disjunctions of literals algebraically.
    coeffs = [(int(c), e) for c, e in coeffs if int(c)]
    if not coeffs:
        return int(bias) > 0

    scale = reduce(gcd, [abs(c) for c, _ in coeffs] + [abs(int(bias))])
    if scale:
        coeffs = [(c // scale, e) for c, e in coeffs]
        bias = int(bias) // scale

    if any(abs(c) != 1 for c, _ in coeffs):
        raise ValueError("Unrecognized affine coefficient identity")

    lits = []
    adjusted = int(bias)
    for c, e in coeffs:
        if c > 0:
            lits.append(e)
        else:
            lits.append(neg(e))
            adjusted -= 1

    if adjusted == 0:
        return combine("or", lits)
    if adjusted == -(len(lits) - 1):
        return combine("and", lits)
    raise ValueError("Affine identity is not an AND/OR of literals")

def decode_row(row, bias, prev):
    coeffs = []
    # Combine coefficients on identical symbolic channels before decoding.
    totals = {}
    for i, value in enumerate(row):
        c = int(round(float(value)))
        if c:
            k = key(prev[i])
            if k not in totals:
                totals[k] = [0, prev[i]]
            totals[k][0] += c
    coeffs = [(c, e) for c, e in totals.values() if c]
    return decode_affine(coeffs, int(round(float(bias))))

def decode_triple(p, m, n):
    # Simplify the documented p + m - n signal using Boolean identities.
    if m is False and n is False:
        return p
    if p is False and m is False and n is False:
        return False
    if p is True and m is False:
        return neg(n)
    if (m is False and same_operands(p, n, "or")
            and len(children(p, "or")) == 2
            and len(children(n, "and")) == 2):
        # The matching OR-minus-AND identity is XOR.
        po = children(p, "or")
        na = children(n, "and")
        if sorted(key(x) for x in po) == sorted(key(x) for x in na):
            return gate("xor", po[0], po[1])
    if p is True and same_operands(m, n, "and"):
        # 1 + AND(a,b) - OR(a,b) = XNOR(a,b).
        if isinstance(n, dict) and n.get("op") == "or":
            na = children(n, "or")
            ma = children(m, "and")
            if sorted(key(x) for x in na) == sorted(key(x) for x in ma):
                return neg(gate("xor", na[0], na[1]))
    if n is False:
        return gate("or", p, m)
    raise ValueError("Unrecognized Boolean triple identity")

h = [inp(i) for i in range(10)] + [False] * 24

